/**
 * Model User
 * Anyone who can sign in. Accounts are deactivated, never deleted,
 * so invoices and payments always point at a real person.
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Swimmer
 * The person taking lessons. A swimmer either has their own login
 * (userId set, role SWIMMER) or is managed by one or more parents.
 */
export type Swimmer = $Result.DefaultSelection<Prisma.$SwimmerPayload>
/**
 * Model ParentSwimmer
 * 
 */
export type ParentSwimmer = $Result.DefaultSelection<Prisma.$ParentSwimmerPayload>
/**
 * Model Stage
 * Ability levels, Stage 1 through Stage 5.
 */
export type Stage = $Result.DefaultSelection<Prisma.$StagePayload>
/**
 * Model StagePrice
 * Price per session for a stage, with history. The rate used for an
 * invoice is the newest row whose effectiveFrom is on or before the
 * enrollment date.
 */
export type StagePrice = $Result.DefaultSelection<Prisma.$StagePricePayload>
/**
 * Model ScheduleTemplate
 * A reusable weekly pattern of lesson slots. Applying a template to a
 * date range creates one Lesson per slot.
 */
export type ScheduleTemplate = $Result.DefaultSelection<Prisma.$ScheduleTemplatePayload>
/**
 * Model TemplateSlot
 * 
 */
export type TemplateSlot = $Result.DefaultSelection<Prisma.$TemplateSlotPayload>
/**
 * Model Lesson
 * A class that meets weekly on one day and time between startDate and
 * endDate. Swimmers enroll in a Lesson; each meeting is a LessonSession.
 */
export type Lesson = $Result.DefaultSelection<Prisma.$LessonPayload>
/**
 * Model LessonSession
 * 
 */
export type LessonSession = $Result.DefaultSelection<Prisma.$LessonSessionPayload>
/**
 * Model Enrollment
 * 
 */
export type Enrollment = $Result.DefaultSelection<Prisma.$EnrollmentPayload>
/**
 * Model Invoice
 * One invoice per enrollment: sessionCount x ratePerSessionCents.
 * Invoices are never deleted. Unpaid ones are voided; paid ones are refunded.
 */
export type Invoice = $Result.DefaultSelection<Prisma.$InvoicePayload>
/**
 * Model Payment
 * Money in (PAYMENT) or out (REFUND). amountCents is always positive.
 */
export type Payment = $Result.DefaultSelection<Prisma.$PaymentPayload>

